const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let desktop=createDesktop(),server=createServer(),course='desktop',scene=null,flowTimer,installTimer,wizardPage=0,config=null;const history=[];
const state=()=>course==='server'?server:desktop,steps=()=>course==='server'?serverSteps:deskSteps;
const details={pc:['Desktop PC','Boot it with the power button and send input over USB. HDMI carries video output; Ethernet handles two-way communication.'],monitor:['Monitor','It needs both power and a video cable. Disconnect HDMI and the PC keeps running, but the picture disappears.'],keyboard:['Keyboard','A USB input device. Disconnecting it stops new keystrokes, but the PC retains text it has already received.'],mouse:['Mouse','It sends movement and button input to the PC. The PC processes that input and updates the screen, using both the input and video connections.'],router:['Router / gateway','It forwards packets between different IP networks. This lab device also provides DNS. Traffic within the same VLAN passes through the switch.'],strip:['Power strip','It supplies power to the PC and monitor. Power and data follow separate paths.'],server:['2U rack server','A conceptual 2U server with a CPU, memory, SSDs, and two power supply modules. Mounting, power, networking, and an operating system must be ready before it can provide services.'],rack:['12U rack','A frame for mounting equipment in standard-sized spaces. Real installations also require cable management, power capacity, weight planning, cooling, and grounding.'],disks:['SSD 480 GB × 2','Choose a single disk or a conceptual RAID 1 mirror in the installer. RAID 1 provides the usable capacity of one disk; you still need a separate backup.'],switch:['Layer 2 switch','It forwards Ethernet frames within a LAN or VLAN. An admin PC and server on the same subnet can still communicate by IP when the router uplink is disconnected.'],ups:['UPS','It provides battery power during an outage. This lab compresses its runtime to 15 seconds. Power stops when the battery runs out; restart the server after restoring power.'],pdu:['PDU','It distributes UPS power to rack equipment. Both PSUs share one PDU in this lab, so they tolerate a PSU failure but not a PDU failure.'],client:['Admin PC','The administrator’s computer at 10.20.0.100. It connects to the server over SSH or requests a page over HTTP. Remember that it is a separate computer.'],console:['Local KVM console','Keyboard, video, and mouse connections let you manage the server directly, even when networking or SSH is unavailable.'],consoleKeyboard:['Console keyboard','It sends input to the local server terminal through KVM, independently of the admin PC’s SSH session.'],media:['Installation USB','Virtual boot media containing the Ubuntu Server installer. Remove it after installation and reboot from disk.'],mains:['Facility power','The start of the power path. When facility power is disconnected, the UPS keeps the rack powered for a limited time.']};
const terminalHTML=`<div class="panel-card"><div class="panel-heading"><div><div class="overline">TRY THE COMMANDS</div><h3>Practice terminal</h3></div><span>Simulated commands in your browser</span></div><div class="terminal-tabs"><button data-session="local" class="active">Server console</button><button data-session="client">Admin PC / SSH</button></div><div class="terminal"><div class="terminal-output" id="terminal-output" role="log" aria-label="Simulated terminal output" aria-live="polite"></div><form class="terminal-form" id="terminal-form"><label class="terminal-prompt" for="terminal-input" id="terminal-prompt">admin@office-web:~$</label><input class="terminal-input" id="terminal-input" aria-label="Simulated Linux command" placeholder="help" autocomplete="off" spellcheck="false"><button type="submit">Run</button></form><div class="terminal-shortcuts"><button data-command="help">help</button><button data-command="ip addr">ip addr</button><button data-command="ping office.example">ping</button><button data-command="systemctl status nginx">nginx status</button><button data-command="curl http://office.example">curl</button><button data-command="sudo ufw status">UFW</button></div><div class="terminal-sim-note">Commands, files, and packets are simulated. No real operating system is installed and no external server is contacted.</div></div></div>`;
const desktopHTML=`<div class="panel-card"><div class="panel-heading"><div><div class="overline">INPUT → PROCESS → OUTPUT</div><h3>Try an input</h3></div><span id="io-status">Waiting for connection</span></div><div class="io-monitor off" id="io-monitor"><div class="screen-caption" id="io-screen-caption">MONITOR / POWER OFF</div><div class="io-screen-output" id="io-screen-output">Connect power and HDMI.</div><div class="io-click-output" id="io-click-output"></div></div><div class="io-controls"><form class="io-input-row" id="io-form"><input id="io-input" aria-label="Virtual keyboard input" placeholder="Type a message for the screen" maxlength="80" autocomplete="off"><button class="secondary-button" type="submit">Send keystrokes</button></form><div class="io-buttons"><button class="secondary-button" id="io-click">${icon('mouse')} Click mouse</button><button class="secondary-button" id="desk-power">${icon('power')} PC power</button><button class="secondary-button" id="desk-ping">${icon('cable')} Ping test</button></div></div><pre class="network-console" id="desk-network">PC → router\nConnect power and LAN, then send a ping.</pre></div>`;
function frame(){const srv=course==='server';$('#system-lab').innerHTML=`<div class="system-shell"><aside class="system-sidebar"><div class="overline">${srv?'OFFICE INFRASTRUCTURE':'YOUR PERSONAL WORKSPACE'}</div><h2>${srv?'Your first server':'It starts with a connection'}</h2><p>${srv?'From rack hardware to Linux and a web service.':'Explore how power, signals, input, and output work together.'}</p><div class="progress-caption"><span>Steps completed</span><span id="system-progress"></span></div><div class="progress-track"><div id="system-progress-fill"></div></div><ol class="systems-steps" id="systems-steps" aria-label="${srv?'Server setup':'Desk setup'} steps"></ol><button class="secondary-button" id="system-reset">${icon('rotate')} Reset this lab</button><div class="sim-only"><strong>LEARNING SIMULATION</strong><br>${srv?'A conceptual model based on Ubuntu Server 24.04 LTS. All disks and networks are virtual.':'Connect or disconnect a device and compare the result. Power and data travel along separate paths.'}</div></aside><div class="system-main"><div class="system-status" id="system-status"></div><div class="system-stage" id="system-stage"><div class="system-canvas" id="system-canvas"></div><div class="stage-heading">${srv?'RACK 01 · OFFICE LAB':'DESK 01 · PERSONAL LAB'}<small>${srv?'2U SERVER / 2× SSD / 32 GB RAM':'ATX PC / HDMI MONITOR / USB / ETHERNET'}</small></div><div class="view-tools"><button class="icon-button" id="system-camera" aria-label="Reset lab camera" title="Reset camera">${icon('rotate')}</button><button class="icon-button" id="system-rear" aria-label="View the back of the lab" title="Rear view">${icon('box')}</button><button class="icon-button" id="system-fullscreen" aria-label="Full-screen lab" title="Full screen">${icon('expand')}</button></div><div class="stage-legend"><span><i class="legend-dot power-color"></i>Power</span><span><i class="legend-dot network-color"></i>Network</span><span><i class="legend-dot usb-color"></i>USB / KVM</span>${srv?'':'<span><i class="legend-dot video-color"></i>Video</span>'}</div><div class="drag-note">Drag to rotate · Scroll to zoom</div></div><div class="system-instruction" aria-live="polite"><div class="overline" id="system-step-tag"></div><h3 id="system-step-title"></h3><p id="system-step-body"></p></div><div class="system-transport"><button class="secondary-button" id="system-prev">${icon('arrow-left')} Previous</button><span class="stage-counter" id="system-counter"></span><button class="primary-button" id="system-next"></button></div></div></div><div class="system-note" id="system-note" role="status">${srv?'Start by mounting the server in the rack. Follow the steps to reach the Linux installer.':'Use the next-step button, or connect and disconnect cables in the panel below.'}</div><div class="ports-panel"><div class="panel-heading"><div><div class="overline">CONNECT / DISCONNECT</div><h3>Take control of the connections</h3></div><span>Click to connect ↔ disconnect</span></div><div class="ports-grid" id="ports-grid"></div><div class="port-hint" id="port-hint">${srv?'Power and data follow separate paths. Click a device to learn what it does.':'A monitor needs power + HDMI, a keyboard and mouse use USB, and networking needs LAN.'}</div></div><div class="system-bottom ${srv?'server-workspace':''}">${srv?terminalHTML:desktopHTML}<div class="panel-card"><div class="panel-heading"><div><div class="overline">FOLLOW THE SIGNAL</div><h3>${srv?'How does a request get there?':'Follow an invisible signal'}</h3></div><span>Live connection state</span></div><div class="flow-panel"><div class="flow-path" id="flow-path"></div><div class="flow-caption" id="flow-caption"></div><div class="device-explanation" id="device-explanation"><strong>${srv?'One server, many connections':'Click a device to explore'}</strong>${srv?'Requests within the LAN pass through the switch. Traffic to other networks needs a gateway.':'Click a device or its label in the 3D model to learn what it does.'}</div><div class="event-log" id="event-log"></div></div>${srv?`<div class="server-web"><div class="address-bar"><span>http://office.example</span><span>Last request result</span></div><div class="web-response offline" id="web-response"><strong>No response yet.</strong><p>Set up Linux and nginx, then send a request.</p></div></div><div class="server-extra"><button class="secondary-button" id="server-request">HTTP request</button><button class="secondary-button" id="server-ip-request">Request by IP</button><button class="secondary-button" id="server-power">Server power</button></div>`:''}</div></div>${srv?`<div class="ports-panel"><div class="panel-heading"><div><div class="overline">BREAK IT. UNDERSTAND IT.</div><h3>Create a fault. Find the cause.</h3></div><span>Click again to recover</span></div><div class="server-summary" id="server-summary"></div><div class="fault-buttons"><button data-fault="psuA">Disconnect PSU A</button><button data-fault="nic">Disconnect server LAN</button><button data-fault="dns">Create DNS fault</button><button data-fault="mains">Power outage · UPS test</button></div><div class="port-hint">Use the local console to recover from a LAN fault. A DNS-only failure blocks domain requests while IP requests still work. Two PSUs connected to one PDU do not provide independent power paths.</div></div><div class="systems-sources"><span><strong>Lab scope</strong> · A simplified small-office setup with one LAN and one server. Real operations also require access policies, patching, monitoring, backup recovery tests, and power and cooling design. The installation screens teach the official installer’s concepts; they do not run the actual installer.</span><span><a href="https://canonical-subiquity.readthedocs-hosted.com/en/latest/tutorial/screen-by-screen.html" target="_blank" rel="noopener">Ubuntu installation guide ↗</a><br><a href="https://ubuntu.com/server/docs/how-to/security/openssh-server/" target="_blank" rel="noopener">OpenSSH documentation ↗</a></span></div>`:'<div class="systems-sources"><span><strong>Each connection has its own role.</strong> USB input becomes available when connected, but a PC that loses power must be restarted. Disconnecting the monitor does not stop the PC. The router and power strip are always powered in this lab.</span></div>'}`;
 $('#system-next').addEventListener('click',runStep);$('#system-prev').addEventListener('click',()=>{state().step=Math.max(0,state().step-1);refresh();});$('#system-reset').addEventListener('click',()=>{if(srv){clearInterval(installTimer);server=createServer();history.length=0;}else desktop=createDesktop();scene?.dispose();frame();});
 $('#systems-steps').addEventListener('click',e=>{const b=e.target.closest('[data-sysstep]');if(b&&!b.disabled){state().step=Number(b.dataset.sysstep);refresh();}});
 $('#ports-grid').addEventListener('click',e=>{const b=e.target.closest('[data-connection]');if(!b)return;const id=b.dataset.connection,c=(srv?serverConnections:desktopConnections).find(c=>c.id===id);toggleConnection(course,state(),id);note(`${c.label} ${state().connections[id]?'Connected':'Disconnected'} · ${c.detail}`);refresh();});
 $('#system-camera').addEventListener('click',()=>scene?.reset());$('#system-rear').addEventListener('click',()=>scene?.rear());$('#system-fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#system-stage').requestFullscreen();}catch{note('Full screen is unavailable in this browser.',true);}});
 if(srv){$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();execute($('#terminal-input').value);$('#terminal-input').value='';});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>execute(b.dataset.command)));document.querySelectorAll('[data-session]').forEach(b=>b.addEventListener('click',()=>{server.session=b.dataset.session;refresh();}));$('#server-request').addEventListener('click',()=>httpRequest(false));$('#server-ip-request').addEventListener('click',()=>httpRequest(true));$('#server-power').addEventListener('click',()=>{if(server.on){server.on=false;server.booted=false;reconcileServer(server);note('Server shut down. Press again to power it on.');}else{const r=serverAction(server,server.installed?'reboot':'boot');note(r.error||r,!!r.error);}refresh();});document.querySelectorAll('[data-fault]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.fault;if(id==='dns'){server.dnsFault=!server.dnsFault;note(server.dnsFault?'DNS fault enabled. Compare a domain request with an IP request.':'DNS responses restored.');event(server,server.dnsFault?'DNS response failed':'DNS working');}else{toggleConnection('server',server,id);note(id==='mains'&&!server.connections.mains?'Facility power lost. The UPS will power the rack for up to 15 seconds.':`${id} ${server.connections[id]?'Recover':'Disconnected'}`);}refresh();}));renderHistory();}
 else{$('#io-form').addEventListener('submit',e=>{e.preventDefault();actDesk('input',$('#io-input').value||'HELLO, PC!');});$('#io-click').addEventListener('click',()=>actDesk('pointer'));$('#desk-ping').addEventListener('click',()=>actDesk('ping'));$('#desk-power').addEventListener('click',()=>{if(desktop.on){desktop.on=false;note('PC shut down.');refresh();}else actDesk('boot');});}
 try{scene=createSystemsScene($('#system-canvas'),course,id=>{const d=details[id]||['Device','A component of the computer system.'];$('#device-explanation').innerHTML=`<strong>${escape(d[0])}</strong>${escape(d[1])}`;});$('#system-canvas').dataset.ready='true';}catch(e){console.error(e);$('#system-canvas').innerHTML='<div class="system-load-error">Cannot display 3D. Please use a browser with WebGL support.<br>The connection and installation exercises below are still available.</div>';}
 setFlow(srv?'network':'input',false);refresh();
}
function note(message,error=false){if(!$('#system-note'))return;$('#system-note').textContent=message;$('#system-note').classList.toggle('error',error);}
function renderHistory(){const out=$('#terminal-output');if(!out)return;out.replaceChildren();if(!history.length){const line=document.createElement('div');line.textContent='PC LAB · simulated Linux console\nType help to see the available commands.\nInstall Linux to use server commands.';out.appendChild(line);}for(const h of history){const el=document.createElement('div');el.className='terminal-line'+(h.command?' command':'');el.textContent=h.text;out.appendChild(el);}out.scrollTop=out.scrollHeight;}
function appendTerminal(command,output,origin=prompt()){if(command)history.push({command:true,text:`${origin} ${command}`});if(output)history.push({text:output});while(history.length>100)history.shift();renderHistory();}
function prompt(){return server.session==='client'?'operator@admin-pc:~$':`${server.user}@${server.host}:~$`;}
function execute(command){if(!command.trim())return;const before=prompt(),r=runCommand(server,command);if(r.clear)history.length=0;else{history.push({command:true,text:`${before} ${command}`},{text:r.output});while(history.length>100)history.shift();}renderHistory();if(r.flow)setFlow(r.flow);refresh();}
function refresh(){if(course==='pc')return;const s=state(),srv=course==='server',list=steps(),done=s.step>=list.length,current=list[Math.min(s.step,list.length-1)],q=srv?serverStatus(s):desktopStatus(s);$('#system-lab').dataset.course=course;$('#system-lab').dataset.step=String(s.step);$('#system-lab').dataset.completed=String(s.completed);$('#system-progress').textContent=`${s.completed} / ${list.length}`;$('#system-progress-fill').style.width=`${s.completed/list.length*100}%`;
 const stepList=$('#systems-steps'),scrollX=stepList.scrollLeft,scrollY=stepList.scrollTop;stepList.innerHTML=list.map((v,i)=>`<li><button data-sysstep="${i}" ${i>s.completed?'disabled':''} class="${i===s.step?'current':i<s.completed?'done':''}" ${i===s.step?'aria-current="step"':''}><span class="step-num">${i<s.completed?icon('check'):String(i+1).padStart(2,'0')}</span><span>${v.name}</span></button></li>`).join('');stepList.scrollLeft=scrollX;stepList.scrollTop=scrollY;if(stepList.dataset.currentStep!==String(s.step)){stepList.dataset.currentStep=String(s.step);const active=stepList.querySelector('.current');if(active){const a=active.getBoundingClientRect(),b=stepList.getBoundingClientRect();if(a.bottom>b.bottom)stepList.scrollTop+=a.bottom-b.bottom+8;if(a.top<b.top)stepList.scrollTop-=b.top-a.top+8;if(a.right>b.right)stepList.scrollLeft+=a.right-b.right+8;if(a.left<b.left)stepList.scrollLeft-=b.left-a.left+8;}}
 $('#system-step-tag').textContent=done?'YOUR LAB IS READY':current.tag;$('#system-step-title').textContent=done?(srv?'Your office server is ready.':'Your desk setup is complete!'):current.name;$('#system-step-body').textContent=done?(srv?'You have installed Linux, connected over SSH, started a web service, and created a backup. Use the fault controls and terminal below to practice diagnosing lost connections.':'You have explored input, output, power, and networking. Disconnect and reconnect cables to discover which functions depend on each connection.'):current.body;$('#system-next').innerHTML=(done?'Review the steps':s.installing?'Installing…':current.button)+icon('arrow-right');$('#system-next').disabled=!!s.installing;$('#system-prev').disabled=s.step===0;$('#system-counter').textContent=`${String(Math.min(s.step+1,list.length)).padStart(2,'0')} / ${list.length}`;
 const pills=srv?[[q.power,'Power'],[q.redundant,'PSU A+B'],[q.running,'Linux'],[q.lan,'IP connectivity'],[q.ssh,'SSH'],[q.http,'HTTP']]:[[q.running,'PC power'],[q.screen,'Display'],[q.keyboard,'Keyboard'],[q.mouse,'Mouse'],[q.network,'Network']];$('#system-status').innerHTML=pills.map(([on,label])=>`<span class="state-pill ${on?'on':''}">${label} ${on?'ON':'OFF'}</span>`).join('')+(srv&&s.batteryActive?`<span class="state-pill warn">UPS ${s.battery}s</span>`:'')+'<span class="sys-simulation-badge">LIVE SIMULATION</span>';
 $('#ports-grid').innerHTML=(srv?serverConnections:desktopConnections).map(c=>`<button class="connection-card ${s.connections[c.id]?'connected':''}" data-connection="${c.id}" aria-pressed="${s.connections[c.id]}" aria-label="${c.label}"><span class="connection-symbol ${c.type}">${icon(c.type==='power'?'power':'cable')}</span><span class="connection-copy"><strong>${c.label}</strong><small>${c.from} → ${c.to}</small></span><span class="connection-state">${s.connections[c.id]?'Connected ↗':'Connect +'}</span></button>`).join('');
 $('#event-log').replaceChildren();s.events.forEach(t=>{const line=document.createElement('div');line.textContent='› '+t;$('#event-log').appendChild(line);});
 if(srv){$('#terminal-prompt').textContent=prompt();document.querySelectorAll('[data-session]').forEach(b=>b.classList.toggle('active',b.dataset.session===(s.session==='remote'?'client':s.session)));$('#server-summary').innerHTML=`<span>Ubuntu ${s.installed?'Installed':'Not installed'}</span><span>${escape(s.host)} · ${escape(s.network.ip)}/24</span><span>${s.storage==='mirror'?'RAID 1 · 480 GB':'Single · 480 GB'}</span><span>Backup ${s.backup?'Available':'None'}</span>`;document.querySelectorAll('[data-fault]').forEach(b=>{const id=b.dataset.fault,fault=id==='dns'?s.dnsFault:!s.connections[id];b.classList.toggle('active',fault);b.setAttribute('aria-pressed',String(fault));b.textContent=({psuA:fault?'Reconnect PSU A':'Disconnect PSU A',nic:fault?'Reconnect server LAN':'Disconnect server LAN',dns:fault?'Restore DNS':'Create DNS fault',mains:fault?'Restore facility power':'Power outage · UPS test'})[id];});$('#server-power').innerHTML=icon('power')+(s.on?'Shut down server':'Power on server');}
 else{$('#io-monitor').classList.toggle('off',!q.screen);$('#io-screen-caption').textContent=!s.connections.monitorPower?'MONITOR / POWER OFF':q.screen?'PC LAB / DESKTOP':'MONITOR / NO SIGNAL';$('#io-screen-output').textContent=!s.connections.monitorPower?'Monitor power is disconnected.':!q.screen?'No video signal.':s.text||'Waiting for your input.';$('#io-click-output').textContent=q.screen?`CLICK ${s.clicks} · ${q.network?'192.168.10.20 / LAN connected':'LAN disconnected'}`:'';$('#io-status').textContent=q.screen?'Display active':'No display';$('#desk-power').innerHTML=icon('power')+(s.on?'Shut down PC':'Power on PC');}
 scene?.update(s);
}
function setFlow(type,animate=true){const srv=course==='server';const data=type==='http-ip'?[['Admin PC','Switch','Server IP :80','200 OK'],'Using an IP address skips DNS lookup. HTTP traffic within the same VLAN passes through the switch without needing the router uplink.']:type==='http-local'?[['Server process','loopback','nginx :80','200 OK'],'A localhost request stays inside the server and never crosses a physical LAN cable. This helps distinguish an external connectivity problem from a service problem.']:type==='loopback'?[['Process','Local IP stack','Reply'],'Requests to a device’s own IP are handled locally. They do not test external communication over a cable.']:type==='ping-gateway'?[['Admin PC / server','Switch','Gateway','ICMP reply'],'Reaching the gateway requires the uplink between the switch and router. That path differs from a request to a server in the same VLAN.']:type==='ping-dns'?[['DNS lookup','Admin PC / server','Switch','Server reply'],'Resolve the name to an IP address, then send an ICMP request. Name resolution and communication with the destination are separate steps.']:type==='input'?[['Keyboard','USB','CPU / OS','GPU','Monitor'],'Keystroke → USB HID report → application processing → display update. The PC can process keyboard input even when HDMI is disconnected.']:type==='pointer'?[['Mouse','USB','Event processing','Monitor'],'The click event reaches the PC, which updates the display. Physical input and video output follow separate paths.']:type==='ssh'?[['Admin PC','Switch','TCP 22','sshd'],'SSH provides encrypted communication within the VLAN. After login, commands are simulated as running on the server.']:type==='http'?[['DNS lookup','Admin PC','Switch','nginx :80','200 OK'],'Resolve the domain to an IP, then send an HTTP request. The web request stays on the local switch; this model uses the router uplink for DNS lookup.']:srv?[['Admin PC','Switch','Server NIC','Reply'],'Local LAN traffic and gateway traffic follow different paths. Disconnecting the uplink still allows access to the server IP within the same VLAN.']:[['PC','Router','ICMP reply'],'The PC sends an ICMP Echo Request to gateway 192.168.10.1 and receives an Echo Reply. The blue dots represent simulated packets.'];$('#flow-path').innerHTML=data[0].map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-node" style="--delay:${i*.25}s">${n}</span>`).join('');$('#flow-caption').textContent=data[1];$('#flow-path').classList.toggle('active',animate);clearTimeout(flowTimer);if(animate){scene?.flow(type);flowTimer=setTimeout(()=>$('#flow-path')?.classList.remove('active'),6500);}}
function actDesk(action,value){const r=desktopAction(desktop,action,value);note(r.error||r,!!r.error);event(desktop,r.error||r);if(action==='ping')$('#desk-network').textContent=r.error?`Connection failed\n${r.error}`:`$ ping 192.168.10.1\n${r}\n4 requests → 4 replies (simulated learning result)`;if(!r.error&&['input','pointer','ping'].includes(action))setFlow(action);refresh();return r;}
function runStep(){const s=state(),list=steps();if(s.step===list.length){s.step=0;refresh();return;}const item=list[s.step];let r;if(course==='desktop')r=actDesk(item.action);else{r=serverAction(s,item.action);if(r.installer){openInstaller();return;}note(r.error||r,!!r.error);event(s,r.error||r);if(!r.error&&['ssh','request','service','firewall','backup'].includes(item.action)){const examples=({ssh:[`ssh ${s.user}@${s.network.ip}`],service:['sudo apt update','sudo apt install nginx'],firewall:['sudo ufw allow OpenSSH','sudo ufw allow 80/tcp','sudo ufw enable'],backup:['backup'],request:['curl http://office.example']})[item.action];examples.forEach((command,i)=>appendTerminal(command,i===examples.length-1?r:'Simulated command completed',item.action==='ssh'?'operator@admin-pc:~$':prompt()));if(item.action==='request')showWeb(r,false);if(['ssh','request'].includes(item.action))setFlow(item.action==='request'?'http':'ssh');}}
 if(!r.error){s.completed=Math.max(s.completed,s.step+1);s.step=Math.min(s.step+1,list.length);}refresh();}
function showWeb(text,error){const out=$('#web-response');if(!out)return;out.classList.toggle('offline',error);out.replaceChildren();const title=document.createElement('strong');title.textContent=error?'The request failed.':server.webContent;const p=document.createElement('p');p.textContent=text;out.append(title,p);}
function httpRequest(byIP){const before=server.session;server.session='client';const r=runCommand(server,'curl http://'+(byIP?server.network.ip:'office.example'));server.session=before;const failed=!r.output.includes('200 OK');showWeb(r.output,failed);note(r.output,failed);event(server,failed?'HTTP request failed':'HTTP 200 OK');if(!failed)setFlow(byIP?'http-ip':'http');refresh();}
function switchCourse(next){if(!['pc','desktop','server'].includes(next))return;const url=new URL(location.href);url.searchParams.set('lab',next);window.history.replaceState(null,'',url);document.dispatchEvent(new Event('coursechange'));scene?.dispose();scene=null;course=next;document.querySelectorAll('[data-course]').forEach(b=>{const active=b.dataset.course===course;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$('#pc-lab').hidden=course!=='pc';$('#components').hidden=course!=='pc';$('#system-lab').hidden=course==='pc';$('#system-lab').setAttribute('aria-labelledby',`course-${course}`);if(course!=='pc')frame();}
document.querySelectorAll('[data-course]').forEach(b=>b.addEventListener('click',()=>switchCourse(b.dataset.course)));document.querySelector('nav a[href="#components"]').addEventListener('click',()=>switchCourse('pc'));

// Simplified installation wizard. Configuration never reaches a real OS or disk.
const dialog=document.createElement('dialog');dialog.id='linux-dialog';dialog.className='linux-dialog';dialog.setAttribute('aria-labelledby','installer-title');document.body.appendChild(dialog);
function openInstaller(){wizardPage=0;config={host:server.host,user:server.user,network:{...server.network},storage:server.storage,language:server.language,keyboard:server.keyboard,sshRequested:server.sshRequested};renderWizard();dialog.showModal();}
function collectConfig(){if(wizardPage===0){config.language=$('#install-language').value;config.keyboard=$('#install-keyboard').value;}if(wizardPage===1){config.network.mode=$('#install-network-mode').value;config.network.ip=config.network.mode==='dhcp'?'10.20.0.50':$('#install-ip').value.trim();config.network.gateway=$('#install-gateway').value.trim();config.network.dns=$('#install-dns').value.trim();}if(wizardPage===2)config.storage=dialog.querySelector('input[name="storage"]:checked').value;if(wizardPage===3){config.host=$('#install-host').value.trim();config.user=$('#install-user').value.trim();config.sshRequested=$('#install-ssh').checked;}}
function renderWizard(){const stageNames=['Basics','Network','Storage','Account · SSH','Review'];let body='';
 if(wizardPage===0)body=`<h3>Hello, Linux.</h3><p>Explore the key installation choices using a model of Ubuntu Server 24.04 LTS. Actual installer screens and options vary by version.</p><div class="install-form"><label>Installation language<select id="install-language"><option ${config.language==='English'?'selected':''}>English</option><option ${config.language==='Korean'?'selected':''}>Korean</option></select></label><label>Keyboard layout<select id="install-keyboard"><option value="us" ${config.keyboard==='us'?'selected':''}>English (US)</option><option value="kr" ${config.keyboard==='kr'?'selected':''}>Korean</option></select></label></div><div class="install-info">Installation media: Ubuntu Server 24.04 LTS · amd64<br>Lab hardware: 32 GB RAM · 2 × 480 GB SSD<br>These choices apply only to the virtual server in this browser.</div>`;
 if(wizardPage===1)body=`<h3>Give your server an address.</h3><p>The lab LAN is 10.20.0.0/24. DHCP assigns an address automatically; a static IP keeps the server at a fixed address.</p><div class="install-form"><label class="full">Address assignment<select id="install-network-mode"><option value="static" ${config.network.mode==='static'?'selected':''}>Static IP</option><option value="dhcp" ${config.network.mode==='dhcp'?'selected':''}>Automatic (DHCP · 10.20.0.50)</option></select></label><label>IPv4 /24<input id="install-ip" value="${escape(config.network.ip)}" ${config.network.mode==='dhcp'?'disabled':''}><small>.1 is the router; .100 is the admin PC.</small></label><label>Gateway<input id="install-gateway" value="${escape(config.network.gateway)}"></label><label class="full">DNS server<input id="install-dns" value="${escape(config.network.dns)}"><small>The DNS service in this lab is at 10.20.0.1.</small></label></div>`;
 if(wizardPage===2)body=`<h3>A home for your operating system.</h3><p>Only the simulated SSDs are initialized. RAID here is a simplified model of mirroring; actual partitioning and redundant UEFI boot require separate configuration.</p><div class="storage-options"><label class="storage-choice"><input type="radio" name="storage" value="mirror" ${config.storage==='mirror'?'checked':''}> RAID 1 · Mirror<small>The same data on two SSDs<br>About 480 GB usable · Tolerates one disk failure</small></label><label class="storage-choice"><input type="radio" name="storage" value="single" ${config.storage==='single'?'checked':''}> Single disk<small>Operating system on one SSD<br>About 480 GB usable · Second disk kept as a spare</small></label></div><div class="install-info">RAID is not a backup. Deleted or corrupted files can affect both copies. Back up to separate storage and test that you can restore it.</div>`;
 if(wizardPage===3)body=`<h3>An administrator. A remote connection.</h3><div class="install-form"><label>Hostname<input id="install-host" value="${escape(config.host)}" maxlength="31" autocomplete="off"></label><label>Administrator username<input id="install-user" value="${escape(config.user)}" maxlength="31" autocomplete="off"></label><label class="full check-label"><input id="install-ssh" type="checkbox" ${config.sshRequested?'checked':''}> Install OpenSSH · Enable simulated public-key authentication</label></div><div class="install-info">The lab generates simulated administrator credentials. Do not enter real passwords or private keys.<br>A real Ubuntu installation requires an administrator password and securely registered SSH public keys. This lab simulates successful public-key authentication.</div>`;
 if(wizardPage===4)body=`<h3>Ready to install with these settings.</h3><div class="install-summary"><div><small>Operating system</small>Ubuntu Server 24.04 LTS</div><div><small>Language / keyboard</small>${escape(config.language)} / ${config.keyboard}</div><div><small>Server / user</small>${escape(config.host)} / ${escape(config.user)}</div><div><small>Network</small>${escape(config.network.ip)}/24 (${config.network.mode})</div><div><small>Virtual storage</small>${config.storage==='mirror'?'RAID 1 · 480 GB':'Single disk · 480 GB'}</div><div><small>SSH</small>${config.sshRequested?'Install · Public-key authentication':'Do not install'}</div></div><div class="install-info">Installation uses only a virtual lab disk. It does not change any disks, files, or settings on your computer.</div>`;
 dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">VIRTUAL INSTALLER / NO REAL DISK ACCESS</div><h2 id="installer-title">Ubuntu Server installation lab</h2><p>${wizardPage+1} / 5 · ${stageNames[wizardPage]}</p><button class="dialog-close icon-button" id="install-close" aria-label="Close installer">${icon('close')}</button></div><div class="install-step-tabs">${stageNames.map((_,i)=>`<span class="${i<=wizardPage?'active':''}"></span>`).join('')}</div><div class="installer-body">${body}</div><div class="installer-error" id="installer-error" role="alert"></div><div class="installer-footer"><button class="secondary-button" id="install-back" ${wizardPage===0?'disabled':''}>Back</button><button class="primary-button" id="install-next">${wizardPage===4?'Install on virtual disk':'Next'} ${icon('arrow-right')}</button></div>`;
 $('#install-close').addEventListener('click',()=>dialog.close());$('#install-back').addEventListener('click',()=>{collectConfig();wizardPage--;renderWizard();});$('#install-next').addEventListener('click',()=>{collectConfig();if(wizardPage===1&&config.network.mode==='dhcp'&&!(serverStatus(server).power&&server.connections.nic&&server.connections.uplink)){$('#installer-error').textContent='No DHCP response. Close the installer and connect the server LAN and router uplink.';return;}const err=wizardPage===1?validateConfig({...config,host:'office-web',user:'admin'}):wizardPage>=3?validateConfig(config):'';if(err){$('#installer-error').textContent=err;return;}if(wizardPage===4)startInstall();else{wizardPage++;renderWizard();}});if(wizardPage===1)$('#install-network-mode').addEventListener('change',e=>{$('#install-ip').disabled=e.target.value==='dhcp';if(e.target.value==='dhcp')$('#install-ip').value='10.20.0.50';});
}
function startInstall(){const q=serverStatus(server);if(!q.power||!server.on||!server.connections.console){$('#installer-error').textContent='Restore power and the KVM connection, then try again.';return;}Object.assign(server,config,{network:{...config.network},installing:true,installed:false,nginx:false,nginxInstalled:false,ssh:false,firewall:false,allowSSH:false,allowHTTP:false});dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">INSTALLING / SIMULATION</div><h2 id="installer-title">Bringing your server to life.</h2><p>Preparing a virtual disk and installing Linux.</p></div><div class="installer-body"><div class="install-progress"><div id="install-progress-bar"></div></div><div class="install-log" id="install-log" role="status"></div></div><div class="installer-footer"><span class="terminal-sim-note">No access to real disks</span><button class="secondary-button" id="install-cancel">Cancel simulated installation</button></div>`;let phase=0;const phases=['Preparing virtual disk / EFI · root','Copying the Linux base system','Configuring hostname, user, and network','Applying your SSH settings','Installation complete · Ready to reboot'];$('#install-cancel').addEventListener('click',()=>{clearInterval(installTimer);server.installing=false;server.installed=false;dialog.close();note('Simulated installation canceled. You can start the installation step again.');refresh();});refresh();clearInterval(installTimer);installTimer=setInterval(()=>{if(!server.installing||!serverStatus(server).power){clearInterval(installTimer);server.installing=false;server.installed=false;dialog.innerHTML='<div class="installer-body"><h3>Installation interrupted.</h3><p>Restore power and run the installation again.</p><button class="primary-button" id="install-interrupted-close">Close</button></div>';$('#install-interrupted-close').addEventListener('click',()=>dialog.close());refresh();return;}phase++;$('#install-progress-bar').style.width=`${phase*20}%`;$('#install-log').textContent=phases.slice(0,phase).map(p=>'✓ '+p).join('\n');if(phase===5){clearInterval(installTimer);server.installing=false;server.installed=true;server.needsReboot=true;server.ssh=server.sshRequested;server.completed=Math.max(server.completed,8);server.step=8;event(server,'Ubuntu Server virtual installation complete');dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">INSTALLATION COMPLETE</div><h2 id="installer-title">Linux is installed!</h2><p>Remove the USB and reboot next.</p></div><div class="installer-body"><div class="install-done">${icon('check')}</div><h3>${escape(server.host)} is ready.</h3><p>${escape(server.network.ip)}/24 · ${server.storage==='mirror'?'RAID 1':'Single disk'} · SSH ${server.ssh?'Installed':'Not installed'}</p><div class="install-info">In the next step, remove the virtual USB and boot into your new operating system.</div><button class="primary-button" id="install-finish">Return to the lab ${icon('arrow-right')}</button></div>`;$('#install-finish').addEventListener('click',()=>dialog.close());refresh();}},900);}
dialog.addEventListener('cancel',e=>{if(server.installing)e.preventDefault();});
setInterval(()=>{if(server.batteryActive&&!server.connections.mains&&server.battery>0){server.battery--;reconcileServer(server);if(course==='server')refresh();}},1000);
const initialCourse=new URLSearchParams(location.search).get('lab');switchCourse(['pc','server'].includes(initialCourse)?initialCourse:'desktop');
